import re
import base64
import binascii

def find_base64(text):
    pattern = r'[A-Za-z0-9+/]{4,}={0,2}'
    matches = re.finditer(pattern, text)
    for match in matches:
        try:
            decoded = base64.b64decode(match.group())
            if not all(c < 127 and c > 31 for c in decoded):
                print(f'Potential binary base64: {match.group()[:60]}...')
        except:
            continue

def find_hex_patterns(text):
    pattern = r'[0-9A-Fa-f]{16,}'
    matches = re.finditer(pattern, text)
    for match in matches:
        try:
            hex_data = binascii.unhexlify(match.group())
            if not all(c < 127 and c > 31 for c in hex_data):
                print(f'Potential binary hex: {match.group()[:60]}...')
        except:
            continue

with open('console.log', 'r') as f:
    content = f.read()
    print('Searching for base64 patterns...')
    find_base64(content)
    print('\nSearching for hex patterns...')
    find_hex_patterns(content)
"
